registerRefData('nsw-cond-n-4322',{"id":4322,"pan":null,"ref":"DA2016 - 465","address":"Ocean Drive, Lake Cathie / Bonny Hills","description":"702 Lot Subdivision","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2017-02-15","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2016NTH018!20190614T222618.358 GMT","sha256":"15536a3fe853e1cf51df44a21b77f1db39fb644f8471d8f24b76bf3f6ab2b318","pages":18,"layout":"numbered","n":11,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/4322.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/702-lot-subdivision","lga":"PORT MACQUARIE-HASTINGS","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. 2016NTH018 - Port Macquarie-Hastings - DA 2016-465.1","stage":"general","stage_basis":"heading","page":2},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT 702 Lot subdivision and associated infrastructure","text":"","stage":"general","stage_basis":"heading","page":2},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 1350 Ocean Drive, Lake Cathie/Bonny Hills","text":"","stage":"general","stage_basis":"heading","page":2},{"label":"4","code":null,"number":"4","title":"APPLICANT","text":"OWNER\nKing and Campbell Pty Ltd\nSt Vincent’s Foundation Pty Ltd","stage":"general","stage_basis":"heading","page":2},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Coastal subdivision","stage":"general","stage_basis":"heading","page":2},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n State Environmental Planning Policy No. 26 - Littoral Rainforest\n State Environmental Planning Policy No. 44 - Koala Habitat\n State Environmental Planning Policy No. 55 - Remediation of Land\n State Environmental Planning Policy No. 64 - Advertising and Signage\n State Environmental Planning Policy No. 71 - Coastal Protection\n State Environmental Planning Policy (Infrastructure) 2007\n State Environmental Planning Policy (State and Regional Development)\n2011\n State Environmental Planning Policy (Rural Lands) 2008\n Port Macquarie-Hastings Local Environmental Plan 2011\n Draft Planning Proposal to amend Port Macquarie-Hastings LEP 2011\n(Amendment No 36)\n Port Macquarie-Hastings Development Control Plan 2013\n Rainbow Beach Central Corridor Planning Agreement\n Ocean Drive Lake Cathie Planning Agreement\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":2},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n Council assessment report: January 2017\n Written submissions during public exhibition: none\n Late submissions from members of the public dated 10 & 14 February\n2017\n Applicant comments on recommended conditions of consent\n Revised draft conditions of consent dated 14 February 2017\n Verbal submissions at the public meeting:\no Support - Ben & Robyn Richardson, Roger Ballard (Bonny Hills\nProgress Association), Sue East (Lake Cathie Progress Association),\n& Phil Hafey (Bonny Hills Progress Association).\no Object - NIL\no On behalf of the applicant - Scott Marchant, King and Campbell\nPty Ltd.","stage":"general","stage_basis":"heading","page":2},{"label":"8","code":null,"number":"8","title":"MEETINGS AND SITE","text":"INSPECTIONS BY THE PANEL  Site visit and briefing meeting on 15 February 2017","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":3},{"label":"10","code":null,"number":"10","title":"","text":"DRAFT CONDITIONS Revised draft conditions of consent dated 14 February 2017 as attached in\nSchedule 2.","stage":"general","stage_basis":"heading","page":3},{"label":"1","code":null,"number":"1","title":"June 2016","text":"In the event of any inconsistency between conditions of this development consent and the plans/supporting\ndocuments referred to above, the conditions of this development consent prevail.\n(2) (A004) An application for a civil works Construction Certificate will be required to be lodged with Port\nMacquarie-Hastings Council prior to undertaking subdivision works and a Subdivision Certificate is required\nto be lodged with Port Macquarie-Hastings Council on completion of works.\n(3) (A006) Approval pursuant to Section 68 of the Local Government Act, 1993 to carry out water supply,\nstormwater and sewerage works is to be obtained from Port Macquarie-Hastings Council.\n(4) (A007) The development may proceed in stages with the infrastructure requirements for each precinct to be\nestablished in accordance with the Statement of Environmental Effects and prior to the first stage of\ndevelopment in any precinct. The approved precincts are set out below:\n Precinct A - 68 residential lots and associated infrastructure.\n Precinct B - 80 residential lots and associated infrastructure.\n Precinct C - 8 residential lots and associated infrastructure.\n Precinct D - 55 residential lots and associated infrastructure.\n Precinct E - 47 residential lots and associated infrastructure.\n Precinct F - 2 residential lots and associated infrastructure.\n Precinct G - 71 residential lots and associated infrastructure.\n Precinct H - 116 residential lots and associated infrastructure.\n Precinct I - 145 residential lots and associated infrastructure.\n Precinct J - 104 residential lots and associated infrastructure.\nUnless specified, the conditions of this consent will apply to all stages, with any decision on any discrepancy\nwith conditions and associated staging resting with Council. Any decision to allow a change to staging will\nrest with Council along with applicable conditions and any contributions payable.\n(5) (A008) Any necessary alterations to, or relocations of, public utility services to be\ncarried out at no cost to council and in accordance with the requirements of the\nrelevant authority including the provision of easements over existing and proposed\npublic infrastructure.\n(6) (A009) The development site is to be managed for the entirety of work in the following manner:\n1. Erosion and sediment controls are to be implemented to prevent sediment from leaving the site. The\ncontrols are to be maintained until the development is complete and the site stabilised with permanent\nvegetation;\n2. Appropriate dust control measures;\n3. Building equipment and materials shall be contained wholly within the site unless approval to use the\nroad reserve has been obtained. Wh ere work adjoins the public domain, fencing is to be in place so as\nto prevent public access to the site;\n4. Building waste is to be managed via an appropriate receptacle;\n5. Toilet facilities are to be provided on the work site at the rate of one toilet for every 20 persons or part of\n20 persons employed at the site.\n6. Building work being limited to the followin g hours, unless otherwise permitted by Council;\n- Monday to Saturday from 7.00am to 6.00pm\n- No work to be carried out on Sunday or public holidays\nThe builder to be responsible to instruct and control his sub-contractors regarding the hours of work.\n(7) (A011) The design and cons truction of all public infrastructure works shall be in accordance with Council’s\nadopted AUSPEC Specifications.\n(8) (A013) The conditions from the following authorities, are attached and form part of the consent conditions\nfor this approval.\n NSW Rural Fire Service - Recommended conditions, Reference D16/2167 DA16070602709 PC and dated\n22 September 2016, are attached and form part of this consent.\n(9) (A016) This consent does not override any requirements of the Native Vegetation Act 2003 and/or the\nEnvironmental Protection and Biodiversity Conservation Act 1999.\n(10) (A029) The provision, at no cost to Council, of co ncrete foot paving for the full street frontages of the\ndevelopment. For Seaside Drive (currently within Lot 1 & Lot 2, DP 1225210) and Wallum Drive (Road #1\nadjacent to the Lot 2, DP 1193553) a 1.2 metre wide footpath is required with design details in accordance\nwith AUSPEC and Council Standard drawings. For Road #3 a 2.5 metre wide shareway (entire length)\nconnecting to the existing shareway along Wallum Driv e (Road #1) with design details in accordance with\nAUSPEC and Council Standard drawings. The design plans must be approved by Council pursuant to\nSection 138 of the Roads Act.\n(11) (A031) Approval pursuant to Section 138 of the Roads Act, 1993 to carry out works required by the\nDevelopment Consent on or within public road is to be obtained from Port Macquarie-Hastings Council.\nSuch works include, but not be limited to:\n Civil works\n Traffic management\n Work zone areas\n Hoardings\n Concrete foot paving\n Footway and gutter crossing\n Functional vehicular access\n Ocean Drive corridor and intersection works\nWhere works are proposed on an RMS classified facility, the Road Authority shall obtain RMS concurrence\nprior to any approval.\n(12) (A032) The developer is responsible for any costs relating to minor alterations and extensions to ensure\nsatisfactory transitions of exist ing roads, drainage and Council services for the purposes of the\ndevelopment.\n(13) (A033) The applicant shall provide security to the Council for the payment of the cost of the following:\na. making good any damage caused to any property of the Council as a consequence of doing anything to\nwhich the consent relates,\nb. completing any public work (such as road work, kerbing and guttering, footway construction, utility\nservices, stormwater drainage and environmental controls) required in connection with the consent,\nc. remedying any defects in any such public work that arise within twelve (12) months after the work is\ncompleted.\nSuch security is to be provided to Council prior to the issue of the Subdivision Certificate/Construction\nCertificate or Section 138 of the Roads Act, 1993.\nThe security is to be for such reasonable amount as is determined by the consent authority, being an amount\nthat is 10% of the contracted works for Torrens Title subdivision development/the estimated cost plus 30%\nfor building development of public works or $5000, whichever is the greater of carrying out the development\nby way of:\ni. deposit with the Council, or\nii. an unconditional bank guarantee in favour of the Council.\nThe security may be used to meet any costs referred to above and on application being made to the Council\nby the person who provided the security any balance remaining is to be refunded to, or at the direction of,\nthat person. Should Council have to call up the bond and the repair costs exceed the bond amount, a\nseparate invoice will be issued. If no application is made to the Council for a refund of any balance remaining\nof the security within 6 years after the work to whic h the security relates has b een completed the Council\nmay pay the balance to the Chief Commissioner of State Revenue under the Unclaimed Money Act 1995.\n(14) (A034) At the terminal end to any public road associated with the given development stage, “dead-end”\nroads are to be extended to AUSPEC standard (AUSPEC D1.5) joining smoothly with the existing section of\nroad ending in a temporary sealed nine (9) metre radii Cul-de-sac with reflectorised posts.\nPrior to Subdivision Certificate, a special terms right of carriageway shall be formed over temporary turning\ncircles to enable the use of the turning area by Council and the public with formal release of the easement\nin full with future road dedication of the turning area.\n(15) (A052) All Sewage Pumping Stations are to be cont ained wholly within a separate lot dedicated to Council\ninclusive of constructed and sealed access handle to the public road.\n(16) (A057) The applicant is to ensure the proposed development will drain to the existing point of connection to\nCouncil’s sewerage system.\n(17) (A195) All environmental works must be carried out in accordance with the relevant Voluntary Planning\nAgreement and approved Vegetation Management Plan.\n(18) (A196) Traffic calming devices are to be incorporated into all roads adjacent to, or crossing Habitat Linkages\nA and D as defined in the adopted Area 14 Koala Plan of Management. Details to be provided on the relevant\ninfrastructure construction certification plans to the satisfaction of Council’s Natural Resource Officer.\n(19) (A200) An appropriate fence consistent with figure 92 of Development Control Plan 2013 - Area Based\nprovisions - Rainbow Beach must be provided along the full length of the littoral rainforest, incorporating\neducational signage at suitable locations. The fence sh all of the same design and tie into that constructed\non the adjoining land being Lot 1 DP374315. Details to be illustrated on the relevant infrastructure\nconstruction certificate plans for precinct F.\n(20) (A201) Prior to the issuing of any Part 4a devel opment certificate all provisions in the executed Voluntary\nPlanning Agreement (VPA), relevant to each precinct or stage, shall be undertaken to the satisfaction of\nCouncil.\n(21) (A202) Any proposed pedestrian crossing across Road #1 shall be designed to accommodate DA 2013/491\n(Lake Cathie Public School) outstanding works required upon completion and dedication of the lead-in road\nto be constructed as part of DA 2013/358. Any pedestrian crossing shall be designed clear of school drop-\noff and loading areas, bus entry and exit driveways, and not impede the function of the Ocean Drive &\nHouston Mitchell Drive intersection.\n(22) (A205) Road #1 adjacent to the woodland shall be designed and constructed with precinct C or D (whichever\noccurs last); and shall be dedicated in conjunction with the first subdivision certificate of lots in that precinct.\n(23) (A206) Road #1 between Road #14 and Seaside Drive (Eastern perimeter road of DA 2012/381) shall be\ndesigned and constructed with the first stage of deve lopment in Precinct G; and shall be dedicated in\nconjunction with the first subdivision certificate of lots in Precinct G.\n(24) (A207) If not already dedicated as part of DA 2012/ 381, Aquatic Way (Road #14 of DA 2012/381) shall be\ndesigned and constructed as part of the first stage of development in Precinct F; and shall be dedicated in\nconjunction with the first subdivision certificate of lots in Precinct F.\n(25) (A208) The Ocean Drive & Baltic Street/Road #2 (Main Street) intersection shall be upgraded to the ultimate\nlayout as per King & Campbell’s plan - Final Ocean Drive Intersection Configuration and referenced by TTM’s\nTraffic Engineering Report (Fig 8.2). Road and intersection work shall include:\n• A channelised intersection with two (2) thr ough lanes in Ocean Drive separated by medians\n• Road #2 (Main Street) south of the intersection shall include:\no two (2) approach and two (2) departure lanes between Ocean Drive & Road #10;\no Unless otherwise agreed to by Port Macquarie-Ha stings Council a raised concrete median island\nprohibiting right-turn movements to/ from Road #10; and\no the provision of a northbound u-turn movement on Road #2 (Main Street) south of the Road #10\nintersection.\n• Sheltered ‘right-turn; bays’\n• Declaration and acceleration lanes suitable fo r the speed zone on both sides of Ocean Drive\n• All required street lighting, signage and line marking\n• Landscaping within the 10 metre wide road widening buffer\n• Signalisation of the intersection wi th pedestrian crossing facilities.\nRoad work and turn lane intersection upgrades for de velopment associated with the intersection shall be\nconstructed as part of the first stage of development in Precinct C; and shall be dedicated in conjunction\nwith the first subdivision certificate in Precinct C. Co st associated with intersec tion works can be offset\nagainst Road Contributions.\n(26) (A209) The Ocean Drive & Solomon Drive/Road #11 intersection shall be upgraded to a two-lane roundabout\nin accordance with Ocean Drive (Area 14) corridor plan widening to a four-lane (dual carriageway) arterial.\nRoad and intersection work shall include:\n• A roundabout intersection with tw o (2) through lanes in Ocean Drive complying with Council AUS-SPEC\nand RMS AUSTROADS standards\n• South leg of Road #11 (departing th e roundabout) be controlled through:\no A raised concrete median prohibiting a southbound right-turn to Lot 68; and\no A raised concrete median ex tending through Road #10 & Road #11 intersection or alternatively a\ndedicated right-turn lane between Ocean Drive and Road #10 creating a dedicated southbound right-\nturn lane.\n• Intersection footpath and cycleway crossings for all approaches\n• All required lighting, signage and linemarking\n• Landscaping within the 10metre wide road widening buffer\n• Provision of bus bay and shelte r facilities where deemed necessary.\n If deemed practicable by Council, a Koala underpass is to be designed and constructed to the satisfaction\nof Port Macquarie-Hastings Council.\nIntersection and road upgrades for development associ ated with the intersection shall be constructed as\npart of the first stage of development in Precinct D or Precinct G; and shall be dedicated in conjunction with\nthe first subdivision certificate in Precinct D or Precinct G. Cost associat ed with intersection works can be\noffset against Road Contributions.\n(27) (A210) Dedication of the road widening buffer (minimum 10m wide) as public road across the frontage of the\ndevelopment and landscaped as per the DCP (Rainbow beach Area 14) as part of the first subdivision\ncertificate for the relevant precinct.\n(28) (A211) As required or warranted, the Ocean Drive & Abel Tasman Drive/Seaside Drive intersection shall be\nincrementally upgraded to the ultimate intersection design (including signalisation) in accordance with the\nOcean Drive (Area 14) corridor plan. Detailed concept pl ans for this ultimate intersection design (including\nsignalisation) at Ocean Drive & Abel Tasman Road inte rsection have been previously defined part of the\nOcean Drive, Lake Cathie Planning Agreement.\nAll costs associated with construction of inte rsection improvements (including but not limited to\nsignalisation, road work, drainage, pedestrian features, utility relocations, street lighting, and line marking)\nshall be at no cost to Port Macquarie-Hastings Council or NSW Roads and Maritime Services. Cost\nassociated with intersection works can be offset against road contributions.\n1. Prior to the issue of the Construction Certificate (for subdivision works) constructing Road #3 between\nRoad #2 (Main Street) to Seawide Drive (within DA 2012/381):\na. Provide detail design plans to upgrade the Ocean Drive & Abel Tasman Drive/Seaside Drive to a\nsignalised intersection consistent with the ultimate intersection design. With Road #3 construction\nworks completed prior to any subdivision certificate to linking Road #2 (Main Street) to Seaside Drive\n(within DA 2012/381).\n(29) (A212) The applicant is to ente r into and comply with the planni ng agreement under section 93F of the\nEnvironmental Planning and Assessment Act 1979, known as the Rainbow Beach Central Corridor Planning\nAgreement dated 22 December 2011 between Port Macquarie Hastings Council and St Vincent’s Foundation\nPty Limited. The planning agreement, as varied or substituted from time to time, is to be performed in\nconnection with the carrying out of the development the subject of this consent.\n(30) (A213) The applicant is to ente r into and comply with the planni ng agreement under section 93F of the\nEnvironmental Planning and Assessment Act 1979, known as the Ocean Drive, Lake Cathie Planning\nAgreement dated 17 February 2015 between Port Macquarie Hastings Council, Catarina Village Pty Limited,\nCatarina Developments Pty Limited, Seawide Pty Limited and St Vincent’s Foundation Pty Limited. The\nplanning agreement, as varied or substituted from time to time, is to be performed in connection with the\ncarrying out of the development the subject of this consent.\n(31) The applicant is to enter into and comply with a planning agreement under section 93F of the Environmental\nPlanning and Assessment Act 1979, between Port Macquarie Hastings Council and St Vincent’s Foundation\nPty Ltd for the:\n• The establishment of the pocket woodland, eastern creek and Lot 5 DP 25886 environmental\nmanagement land;\n• The management of the pocket woodland, eastern creek and Lot 5 DP 25886 environmental\nmanagement land for a period of 20 years, or as agreed between parties, from the completion of the\nestablishment period for each of the subject areas; and\n• The dedication of the pocket woodland, eastern creek and Lot 5 DP 25886 environmental management\nland to Council at the completion of the management period for each of the subject areas.\nThe planning agreement, as varied or substituted from time to time, is to be performed in connection with\nthe carrying out of the development the subject of this consent.\n(32) All residential lots are to have a finished surface level which is a minimum of 400mm above the 1 in 100 year\nincluding climate change flood levels as specified in the Car dno Flood Assessment Report (June 2016) or\nthe Cardno Water Engineering and Environment DGR Assessment - Chapter 4 (April 2010) (whichever is\nhigher).\nNote: The finished floor levels of all future residential dwellings will be required to be a minimum of 500mm\nabove the 1 in 100 year including climate change flood levels as specified in the Cardno Flood Assessment\nReport (June 2016) or the Cardno Water Engineering and Environment DGR Assessment - Chapter 4 (April\n2010) (whichever is higher).\n(33) All roads and bridges are to have a finished surface level which is at or above the 1 in 100 year including\nclimate change flood levels as specified in the Cardno Flood Assessment Report (June 2016) or the Cardno\nWater Engineering and Environment DGR Assessment - Chapter 4 (April 2010) (whichever is higher).\n(34) The final extent of fill for the western batter of proposed road 07 abutting Duchess Creek must be refined at\ndetail design stage. The design shall demonstrate that there would be no more than 10mm afflux present in\nthe upstream areas and no more than 0.1m/s increase in flood velocity as a result of the road batter\ntreatment.\n(35) Prior to the release of the infrastructure Construc tion Certificate for landscaping works in precinct C the\nstreet tree plan shall be updated to replace Tallowwood species to anot her native non-Koala food tree for\nthe median. Advice should be sought from Port Macquarie-Hastings Council’s management staff as to a\nsuitable species for this location.\n(36) An appropriately sized fauna underpass in the Easter n Creek Habitat Corridor crossing shall be constructed\nfor road No. 1. It shall be designed and constructed to the satisfaction of Port Macquarie-Hastings Council.\nDetails to be illustrated on the relevant stage/precinct infrastructure construction certificate plans.\n(37) Koala proof fencing is to be installed on both si de of Duchess creek corridor, from Ocean Drive to the first\nroad crossing over duchess creek to the satisfaction of Port Macquarie-Hastings Council. Three (3) one-way\nKoala bridges are to be installed at the interface of the habitat corridor and Ocean Drive. Details to be\nillustrated on the relevant stage/precinct infrastructure construction certificate plans.\n(38) The developer is to undertake feasibility study in providing a appropriately sized koala underpass as part of\nthe construction of the Solomon Road / Ocean Drive intersection roundabout. The findings and details shall\nbe presented as part of the infrastructure Construction Certificate.\nB - PRIOR TO ISSUE OF A CIVIL WORKS CONSTRUCTION CERTIFICATE\n(1) (B003) Submission to the Principal Certifying Authority prior to the issue of a civil works Construction\nCertificate relevant to each stage/precinct detailed design plans for the following works associated with the\ndevelopments. Public infrastructure works shall be constructed in accordance with Port Macquarie-Hastings\nCouncil’s current AUSPEC specifications and design plans are to be accompanied by AUSPEC DQS:\n1. Road works along the frontage of the development.\n2. New roads within the subdivision.\n3. Earthworks, including filling of the land for flood protection.\n4. Public parking areas including;\na. Driveways and access aisles;\nb. Parking bays;\nc. Delivery vehicle service bays & turning areas\nin accordance with AS 2890.\n5. Sewerage reticulation.\n6. Water supply reticulation.\n7. Stormwater systems.\n8. Erosion & Sedimentation controls.\n9. Location of all existing and proposed utility services including:\na. Conduits for electricity supply and communication services (including fibre optic cable).\nb. Water supply\nc. Sewerage\nd. Stormwater\n10. Open space facilities, pathways, cycleways and associated facilities.\n11. Landscaping.\n12. Bridges/Major Culverts.\n13. Provision of a bus bay in accordance with Council ’s adopted Development Control Plan and AUSPEC\nrequirements and shelter in accordance with Council standard drawings.\n14. Provision of a paved and signed cycleway route along Road #1 in accordance with Council’s adopted\nDevelopment Control Plan and AUSPEC requirements.\n15. Provision of pedestrian access ways a minimum of 4m wide, from Road Number 8 to Ocean Drive; such\naccess ways to include a concrete pathway 1.2m wide including kerb ramps where necessary.\n16. Minimum provision of a 1.2m concrete footpath across the full road frontage of all roads.\n17. Detailed intersection layout at the junctions of Ocean Drive & Baltic Street/Road #2 (Main Street); Ocean\nDrive & Solomon Drive; and Ocean Drive & Seaside Drive (traffic signals) in accordance with the current\nversion of the AUSTROADS guidelines for Intersection design, giving particular attention to sight\ndistance.\n18. Provision of fire trails with the current version of Planning for Bush Fire Protection.\n19. The slope of the cut/fill batter shall be in accordance with Counc il’s adopted AUSPEC Design and\nConstruction Guidelines. Adequate safety fencing is to be provided if maximum batter slope is\nexceeded.\n(2) (B004) Road network within the subdivision is to be categorised with carriageway width as follows. Prior to\nrelease of a civil works Construction Certificate releva nt to each stage/precinct such details are to be\nillustrated on the submitted plans.\nRoad Name\nRoad Reserve\n(Carriageway)* Road Category\nRoad No. 1 Width (m): 20 (9) Collector Road\nRoad No. 2\n(south of Road 1)\nWidth (m): 20 (9) Collector Road\nRoad No. 2\n(north of Road 1)\nWidth (m): 31.5 (22.5) Commercial Road\n(Main Street)\nRoad No. 3 Width (m): 16 (9)\n(w/ on-street parking)\nCollector Road\n(Perimeter Road)\nRoad No. 4 Width (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 5\n(north-south road)\nWidth (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 5\n(east-west road)\nWidth (m): 15 (7) Local Street\nRoad No. 6 Width (m): 15 (7) Local Street\nRoad No. 7 (east road) Width (m): 19 (9) Collector Road\nRoad No. 7 (west road) Width (m): 16 (8) Perimeter Road\nRoad No. 8\n(adjacent to Eastern\nCreek)\nWidth (m): 20 (8) Local Street (Perimeter\nRoad Special)\nRoad No. 8 (not\nadjacent to Eastern\nCreek)\nWidth (m): 15 (7) Local Street\nRoad No. 9 Width (m): 15 (7) Local Street\nRoad No. 10\n(east of Road 16)\nWidth (m): 15 (7) Local St (with Collector\nRoad Pavement)\nRoad No. 10 (between\nRoad 16 & Road 24)\nexcept through lot 696\nWidth (m): 16 (9) Commercial Road\nRoad No. 10\n(west of Road 24)\nWidth (m): 15 (7) Local St (with Collector\nRoad Pavement)\nRoad No. 11 Width (m): 20 (9) Collector Road\nRoad No. 12 Width (m): 15 (7) Local Street\nRoad No. 13\n(north-south road)\nWidth (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 13\n(east-west road)\nWidth (m): 15 (7) Local Street\nRoad No. 14\n(north of road 12)\nWidth (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 14\n(south of road 12)\nWidth (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 15 Width (m): 15 (7) Local Street\nRoad No. 16 Width (m): 16 (9)\n(w/ on-street parking)\nCollector Road\n(Perimeter Road)\nRoad No. 17 Width (m): 15 (7) Local Street\nRoad No. 18 Width (m): 15 (7) Local Street\nRoad No. 19 Width (m): 15 (7) Local Street\nRoad No. 20 Width (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 21 (east of\nroad 20)\nWidth (m): 15 (7) Local Street (Drainage\nReserve Edge Road)\nRoad No. 21 (west of\nroad 20)\nWidth (m): 15 (7) Local Street\nRoad No. 22 Width (m): 15 (7) Local Street\nRoad No. 23 Width (m): 15 (7) Local Street\nRoad No. 24 Width (m): 15 (7) Commercial Road\nRoad No. 25 Width (m): 15 (7) Local Street\nRoad No. 26 Width (m): 15 (7) Local Street\nRoad No. 27 Width (m): 15 (7) Local Street\nRoad No. 28 Width (m): 15 (7) Local Street\nRoad No. 29 Width (m): 15 (7) Local Street\nRoad No. 30 Width (m): 15 (7) Local Street\nRoad No. 31 Width (m): 15 (7) Local Street\nRoad No. 32 Width (m): 15 (7) Local Street\nRoad No. 33 Width (m): 15 (7) Local Street\nRoad No. 34 Width (m): 15 (7) Local Street\nRoad No. 35 Width (m): 15 (7) Local Street\nNote: * Reserve and carriageway widths shall comply with most recent version of AUSPEC and\nNSW Planning for Bushfire Protection (PBP). Localised road widening may be required in\naccordance with Table 4.1 of PBP for any horizontal curves less than 70m. Minimum\nverge widths shall be maintained in accordance with AUSSPEC.\n(3) (B007) Road names proposed for the development sha ll be submitted to Port Macquarie-Hastings Council\nprior to release of a civil works Construction Certificat e relevant to the stage/precinct. A suitable name for\nany new road(s) shall be in accordance with the NSW Addressing User Manual.\n(4) (B008) This consent approves the staging of the subdivision subject to:\na. the applicant supplying an updated staging plan when lodging a civil works Construction Certificate\napplication showing each of the preceding stages and the proposed stages of the subdivision;\nb. compliance with any other conditions of consent in relation to the staging of works.\n(5) (B015) Provision to each lot of a separate water connection (un-metered and sealed) to Council’s main.\n(6) (B016) Provision to each lot of a separate sewer line to Council’s main. All work will need to comply with\nthe requirements of Council’s adopted AUSPEC Desi gn and Construction Guidelines and Policies. Any\nabandoned sewer junctions are to be capped off at Council’s sewer main.\nConstruction details are to be submitted to Port Macquarie-Hastings Council with the application for civil\nworks Construction Certificate.\n(7) (B019) The local water supply reticulation mains are to loop within the subdivision to minimise dead ends\nand connect to the existing reticulation wherever possible.\n(8) (B030) Prior to issue of a civil works Construction Certificate relevant to the stage/precinct, a pavement\ndesign report shall be prepared by a suitably qualified geotechnical or civil engineer and submitted to Port\nMacquarie-Hastings Council, including soil test results and in-situ CBR values (NATA certified). Council’s\nminimum pavement compaction testing criteria are as follows:\na. 98% (modified) base layers - Maximum Modified Dry Density test in accordance with AS1289.5.2.1\nb. 95% (modified) sub-base layers - Maximum Modified Dry Density test in accordance with AS1289.5.2.1\nc. 100% (standard) subgrade/select layers - Maximum Standard Dry Density test in accordance with\nAS1289.5.1.1 (or for in-situ subgrade soils only, wet density testing may be used)\n(9) (B031) Prior to release of a civil works Constructi on Certificate relevant to each stage/precinct an execution\nof a Works Authorisation Deed (WAD) with The Roads and Maritime Services (RMS) or evidence of agreement\nfrom the RMS that no WAD is required.\n(10) (B034) Prior to release of a civil works Construc tion Certificate relevant to each stage/precinct the\nsubmission of details to Council for the disposal of any spoil gained from the site and/or details of the source\nof fill, heavy construction materials and proposed routes to and from the site, including, but not limited to:\n The pavement condition of the route/s proposed (excluding collector, sub-arterial and arterial roads) for\nthe haulage of fill material to the site and/or haulage of excess material from the site. The condition\nreport shall include photographs of the existing pavement and pavement deflection test results taken in\nthe travel lanes;\n Recommended load limits for haulage vehicles and;\n A procedure for monitoring the condition of the pavement during the haulage;\n Bond to guarantee public infrastructure is not damaged as a result of construction activity,\nand;\nCouncil shall determine the need for and extent of any rectification work on the haulage route/s considered\nattributable by the haulage of materials to and/or from the site.\n(11) (B072) A stormwater drainage design is to be submitted and approved by Port\nMacquarie-Hastings Council prior to the issue of a civil works Construction Certificate\nrelevant to the stage/precinct. The design must be prepared in accordance with Port\nMacquarie-Hastings Council’s AUSPEC Specifications and the requirements of\nRelevant Australian Standards and make provision for the following:\na) The design is to be generally in accordance with the stormwater drainage concept\nplan on Drawing No 5709 prepared by King and Campbell Pty Ltd and dated April\n2016.\nb) All allotments must be provided with a direct point of connection to the public piped\ndrainage system. Kerb outlets are not permitted.\nc) The design shall incorporate on-site stormwater detention facilities to limit site\nstormwater discharge to pre development flow rates for all storm events up to and\nincluding the 100 year ARI event. Note that pre development discharge shall be\ncalculated assuming that the site is a ‘greenfield’ development site as per AUSPEC\nrequirements.\nd) The design shall include water quality controls designed to achieve the targets\nspecified within AUSPEC D7.\ne) Where works are staged, a plan is to be provided which demonstrates which\ntreatment measure/s is/are are to be constructed with which civil works stage.\nSeparate plans are required for any temporary treatment (where applicable e.g. for\nbuilding phase when a staged construction methodology is adopted) and ultimate\ndesign.\nf) The design is to make provision for the natural flow of stormwater runoff from\nuphill/upstream properties/lands. The design must include the collection of such\nwaters and discharge to the Council drainage system.\ng) An inspection opening or stormwater pit must be installed inside the property,\nadjacent to the boundary, for all stormwater outlets.\n(12) (B052) The provision of 3m x 3m splay corners on corner allotments or otherwise agreed to by Port\nMacquarie-Hastings Council. Details must be subm itted to and approved by Port Macquarie-Hastings\nCouncil prior to release of the civil works Construction Certificate relevant to that stage/precinct.\n(13) (B071) Prior to the issue of a civil works Constructi on Certificate relevant to the stage/precinct, the provision\nof water and sewer services to the land are to be approved by the relevant Water Authority and relevant\npayments received.\n(14) (B073) A dilapidation report on the visible and structur al condition of the following public infrastructure must\nbe provided to Council prior to the issue of a civ il works Construction Certificate within the relevant\nstage/preicinct.\n Stormwater network within the central corridor\nThe dilapidation report is to be prepared by a pract ising Structural/Civil Engineer agreed to by both the\napplicant and Port Macquarie-Hastings Council. All costs incurred in achieving compliance with this\ncondition shall be borne by the applicant.\nThe applicant shall be responsible for public infrastructure. Any damage to public infrastructure in the\nvicinity of the site, where such damage is not accurately recorded by the requirements of this condition will\nbe borne by the applicant.\n(15) (B085) The location of electricity substations are to be clearly illustrated on the civil works Construction\nCertificate plans. All substations are to remain on private property unless otherwise agreed to by Port\nMacquarie-Hastings Council.\n(16) (B195) The sewer and water supply strategy shown on Exhibit 06 - Residential Servicing (Sewer & Water) is\nnot generally acceptable. In particular, approximately 300 metres of 200mm potable water main is to extend\nsouth from Precinct I to the existing 200mm PVC water main in Rainbow Beach Drive and address possible\nadditional flow from SPS 12 with attendant grade reduction within the development and perhaps elimination\nof one new Sewer Pump Station.\n(17) (B196) Prior to issue of a civil works Construction Certifi cate for the relevant stage/precinct, the proponent\nis to provide a development staging plan as well as a finished surface contour plan together with water\nsupply (potable and reclaimed) and sewer servici ng strategies detailing works necessary to support each\nstage. Potable and reclaimed water supply modelling will be prov ided by Port Macquarie-Hastings Council\nin regard to proposed water main sizing, main locations and augmentations.\n(18) (B199) WAD - Ocean Drive & Baltic St / Road #2 (Main Street) Intersection\nWhen traffic control signals are requi red on a classified road, the developer will be required to enter into a\nWorks Authorisation Deed (WAD) with RMS, which will exercise its power under Section 87 of the Roads Act\n1993 (the Act) and/or the functions of the roads authority, to oversee the traffic control signals in accordance\nwith Sections 64 and 71, as applicable, for all works under the WAD.\nUpon Council’s determination of the warrants for signalisation of the Ocean Drive - & Baltic Street / Road #2\n(Main Street) intersection, the developer shall enter into a WAD with RMS for all road works associated with\nthe installation of traffic control signals on the classified road (Ocean Drive).\nUpon Council’s determination of the warrants for signalisation of the Ocean Drive - & Baltic Street / Road #2\n(Main Street) intersection, the developer shall complete all road works associated with the installation of\ntraffic control signals as required under the WAD to practical completion, as determined by RMS, prior to\nissuing any further subdivision certificate for the proposed subdivision. All works shall be undertaken at full\ncost to the developer to the satisfaction of RMS. Co st associated with intersection works can be offset\nagainst Road Contributions.\n(19) (B200) WAD - Ocean Drive & Seaside Drive Intersection\nWhen traffic control signals are required on a classified road. The developer will be required to enter into a\nWorks Authorisation Deed (WAD) with RMS, which will exercise its powers under Section 87 of the Roads\nAct 1993 (The Act) and/or the functions of the roads authority, to oversee the Traffic control signals in\naccordance with Sections 64 and 71, as applicable, for all works under the WAD.\nUpon Council’s dete rmination of the warrants for signalisati on of the Ocean Drive - Abel Tasman\nintersection, the developer shall enter into a WAD with RMS for all road works associated with the installation\nof Traffic Control Signals on the classified road (Ocean Drive).\nUpon Council’s determination of the warrants for the signalisation of the Ocean Drive - Abel Tasman\nintersection the developer shall complete all road wor ks associated with the installation of traffic control\nsignals as required under the WAD to practical completion, as determined by RMS, prior to issuing any\nfurther subdivision certificate for the proposed subdivision. All works shall be undertaken at full cost to the\ndeveloper to the satisfaction of RMS. Cost associated with intersection works can be of fset against Road\nContributions.\n(20) (B201) Design Plans to Road and Maritime Servic es (RMS) - Approved design plans by the RMS of the\nproposed engineering works detailed below shall be submitted to the Council as the Road Authority for\napproval prior to the issue of a Construction Certificate for intersection works for the relevant stage/precinct.\n• Ocean Drive & Abel Tasman Road intersection improvements and signalisation\n• Ocean Drive & Baltic Street/Road #2 (Main Street) intersection improvements and signalisation\n(21) The three grassed stormwater channels located centrally within drainage catchments W1C, W1E and W2\nmust be landscaped with endemic native species that require no specific regular maintenance for bushfire\nprotection purposes. In this regard it is noted that these channels and located within an “Inner Protection\nArea” as specified within the Bushfire Protection Assessment Report.\nSuch landscaping shall be planted at sufficient densities to discourage natural regeneration of tree species.\nA detailed landscaping plan for all vegetated stormwater assets must be submitted to and approved by\nCouncil’s Transport and Stormwater Network section pr ior to the issue of a civil works Construction\nCertificate relevant to the stage/precinct.\n(22) Prior to the issue of any Construction Certificate, the developer is to provide evidence of Rainbow Beach\nCentral Corridor Planning Agreement and Ocean Drive Lake Cathie Planning Agreement has been registered\non the title.\nC - PRIOR TO ANY WORK COMMENCING ON SITE\n(1) (C001) A minimum of one (1) week’s notice in writing of the intention to commence works on public land is\nrequired to be given to Port Macquarie-Hastings Council together with the name of the principal contractor\nand any major sub-contractors engaged to carry out works. Works shall only be carried out by a contractor\naccredited with Port Macquarie-Hastings Council.\n(2) (C002) Prior to the commencement of any works, a pre-construction meeting shall be\norganised by the applicant. This meeting is to be attended by the applicant or\nconsultants, principal contractor and Port Macquarie-Hastings Council's development\nengineer or his representative.\n(3) (C008) No access through public reser ve land shall be allowed without first obtaining written approval from\nPort Macquarie-Hastings Council's Parks and Gardens Manager. No clearing or damage to any vegetation\non public reserve land is permitted. No spoil, fill, waste liquids or solid materials shall be stockpiled on or\nallowed to move beyond the fence line for any period on the adjoining public reserve land during or after the\ndevelopment. In the event of accidental damage, the si te must be revegetated to the satisfaction of Port\nMacquarie-Hastings Council. Such approval would need to be undertaken in accordance with Council Policy.\n(4) (C013) Where a sewer manhole exists within a property, access to the manhole shall be made available at all\ntimes. Before during and after construction, the sewer manhole must not be buried, damaged or act as a\nstormwater collection pit. No structures, including reta ining walls, shall be erected within 1.0 metre of the\nsewer manhole or located so as to prevent access to the manhole.\n(5) (C015) Tree protection fencing, compliant with AS 4970/2009 Protection of trees on development sites must\nbe provided. The fencing shall be in place prior to the commencement of any works or soil disturbance and\nmaintained for the entirety of the works.\n(6) Prior to any works commencing within precinct D a Vegetation Management Plan for the Pocket Woodland\nPark (proposed Lot 697) is to be approved by Port Macquarie-Hastings Council.\nD - DURING WORK\n(1) (D001) Development works on public property or works to be accepted by Port Macquarie-Hastings Council\nas an infrastructure asset are not to proceed past the following hold points without inspection and approval\nby Council. Notice of required inspection must be given 24 hours prior to inspection, by contacting Council’s\nCustomer Service Centre on (02) 6581 8111. You must quote your Construction Certificate number and\nproperty description to ensure your inspection is confirmed:\na. prior to commencement of site clearing and installation of erosion control facilities;\nb. at completion of installation of erosion control measures\nc. prior to installing traffic management works\nd. at completion of installation of traffic management works\ne. at the commencement of earthworks;\nf. before commencement of any filling works;\ng. when the sub-grade is exposed and prior to placing of pavement materials;\nh. when trenches are open, stormwater/water/sewer pipes and conduits jointed and prior to backfilling;\ni. at the completion of each pavement (sub base/base) layer;\nj. before pouring of kerb and gutter;\nk. prior to the pouring of concrete for sewerage works and/or works on public property;\nl. on completion of road gravelling or pavement;\nm. during construction of sewer infrastructure;\nn. during construction of water infrastructure;\no. prior to sealing and laying of pavement surface course.\nAll works at each hold point shall be certified as compliant in accordance with the requirements of AUSPEC\nSpecifications for Provision of Public Infrastructure and any other Council approval, prior to proceeding to\nthe next hold point.\n(2) (D006) A copy of the current stamped approved construction plans must be kept on site for the duration of\nsite works and be made available upon request to either the Principal Certifying Authority or an officer of\nthe Council.\n(3) (D029) The demolition of any existing structures sha ll be carried out in accordance with Australian Standard\nAS 2601-1991: The Demolition of Structures . No demolition materials shall be burnt or buried on site. The\nperson responsible for the demolition works shall ensure that all vehicles leaving the site carrying\ndemolition materials have their loads covered and do not track soil or waste materials onto the road. Should\nthe demolition works obstruct or inconvenience pedestrian or vehicular traffic on an adjoining public road\nor reserve, separate application shall be made to Council to enclose the public place with a hoarding fence.\nShould asbestos be present, its re moval shall be carried out in accordance with the National OH&S\nCommittee - Code of Practice for Safe Removal of Asbestos and Code of Practice for the Management and\nControl of Asbestos in Workplaces.\n(4) (D033) Should any Aboriginal objects be discovered in any areas of the site then all excavation or\ndisturbance to the area is to stop immediately and th e National Parks and Wildlife Service, Department of\nEnvironment and Conservation is to be informed in accordance with Section 91 of the National Parks and\nWildlife Act 1974. Subject to an assessment of the extent, integrity and significance of any exposed objects,\napplications under either Section 87 or Section 90 of the National Parks and Wildlife Act 1974 may be\nrequired before work resumes.\n(5) (D037) Noise from construction activities (measure as the L AeqT noise level) shall not exceed the background\nnoise level (measured as the L A90 noise level in the absence of the source), for periods of construction\nbetween 4 and 26 weeks by 10 dB(A), and for periods of construction exceeding 26 weeks by 5 dB(A), in any\nOctave Band Centre Frequency, when measured at any affected residence, or premises.\n(6) Adequate measures being taken to prevent dust from affecting the amenity of the neighbourhood during\nconstruction. In particular, the following measures must be adopted:\n Earthworks and scheduling activities shall be managed to coincide with the next stage of\ndevelopment to minimise the amount of time the site is left cut or exposed;\n The work areas being dampened slightly to prevent dust from becoming airborne but not to the\nextent that runoff occurs;\n All vehicles carrying spoil or rubble to or from th e site shall at all times be covered to prevent\nthe escape of dust or other materials;\n All equipment wheels shall be washed before exiting the site using manual or automated\nsprayers and drive through washing bays (if applicable).\n(7) (D040) Wastes including cleared vegetation shall not be disposed of by burning.\n(8) (D051) Prior to commencement of any pavement works a material quality report from the proposed supplier\nshall be submitted to Port Macquarie-Hastings Council. The pavement materials shall meet Council’s current\nspecifications at the time of construction.\n(9) (D052) Prior to laying of Asphaltic Concrete (AC) or wearing surface course,\nsubmission to Port Macquarie-Hastings Council of pavement and soil test results\nprepared by a NATA registered person for all road pavement construction, including:\na.\nCBR test results, and\nb. Subgrade / select fill, sub-base and base pavement compaction reports in accordance with\nAS1289.5.1.1 & AS1289.5.2.1 as applicable.\nE - PRIOR TO THE ISSUE OF SUBDIVISION CERTIFICATE\n(1) (E004) Consolidation of the allotments comprising the site of the proposed development prior to or as part\nof the application for a Subdivision Certificate.\n(2) (E005) Prior to the release of an y bond securities held by Port Macquarie-Hastings Council for infrastructure\nworks associated with developments, a formal written application is to be submitted to Council specifying\ndetail of works and bond amount.\n(3) (E006) Completion of engineering a nd environmental works for any land (other than proposed public roads)\nto be transferred to Port Mac quarie-Hastings Council, in accordance with the approved Construction\nCertificate.\n(4) (E008) Payment to Council, prior to the issue of th e Subdivision Certificate of the Section 94 contributions\nset out in the “Notice of Payment - Developer Charges” schedule attached to this consent unless deferral\nof payment of contributions has been approved by Council, or a planning agreement has been entered into\nwith Council to address the relevant plans. The contributions are levied, pursuant to the Environmental\nPlanning and Assessment Act 1979 as amended, and in accordance with the provisions of the following\nplans:\n Hastings S94 Administration Building Contributions Plan\n Hastings Administration Levy Contributions Plan\n Hastings S94 Major Roads Contributions Plan\n Hastings S94 Open Space Contributions Plan\n Section 94 Local Roads Contributions Plan Areas 13, 14 and 15\n Community Cultural and Emergency Services Contributions Plan 2005\nThe plans may be viewed during office hours at the Council Chambers located on the corner of Burrawan\nand Lord Streets, Port Macquarie, 9 Laurie Street, Laurieton, and High Street, Wauchope.\nThe attached “Notice of Payment” is valid for th e period specified on the Notice only. The contribution\namounts shown on the Notice are subject to adjustment in accordance with CPI increases adjusted quarterly\nand the provisions of the relevant plans. Payments can only be made using a current “Notice of Payment”\nform. Where a new Notice of Payment form is required, an application in writing together with the current\nNotice of Payment application fee is to be submitted to Council. Cost associated with intersection works can\nbe offset against Road Contributions.\n(5) (E009) As part of Notice of Requirements by Port Macquarie-Hastings Council as the Water Authority under\nSection 306 of the Water Management Act 2000, the payment of a cash contribution, prior to the issue of a\nSubdivision Certificate, of the Section 64 contributions, as set out in the “Notice of Payment - Developer\nCharges” schedule attached to this consent unless deferral of payment of contributions has been approved\nby Council. The contributions are le vied in accordance with the provisi ons of the relevant Section 64\nDevelopment Servicing Plan towards the following:\n augmentation of the town water supply headworks\n augmentation of the town sewerage system headworks\n(6) (E012) Dedication as public road to Port Macquarie-Hastings Counci l, the area required for road widening\nalong the frontage of the development at no cost to Council. Details are to be incorporated in the plan of\nsubdivision for the relevant stage/precinct.\n(7) (E015) Prior to the issue of a Subdivision Certificate for residential lots, detail s of compliance with the\nbushfire safety conditions is to be provided to the Principal Certifying Authority.\n(8) (E034) Prior to the issuing of a Subdivision Certific ate for the relevant stage/ precinct provision to the\nPrincipal Certifying Authority of documentation from Port Macquarie-Hastings Council being the local roads\nauthority certifying that all matters required by the approval issued pursuant to Section 138 of the Roads\nAct have been satisfactorily completed.\n(9) (E035) Prior to the issuing of the Subdivision Certif icate for the relevant stage/precinct, provision to the\nPrincipal Certifying Authority of documentation from the Roads and Maritime Services (RMS) being the roads\nauthority certifying that all matters required by appr oval issued by Section 61 and/or Section 138 of the\nRoads Act have been satisfactorily completed. A copy of this is to be submitted to Port Macquarie-Hastings\nCouncil prior to the release of the engineering security bond.\n(10) (E038) Interallotment drainage shall be piped and centrally located within an inter-\nallotment drainage easement, installed in accordance with Council’s current AUSPEC\nstandards (minimum 225mm pipe diameter within a minimum 1.5m easement). Details\nshall be provided:\n As part of a Local Government Act (s68) application with evidence of registration of\nthe easement with the Land Titles Office provided to Council prior to issue of the s68\nCertificate of Completion; or\n As part of a Construction Certificate application for subdivision works with\ndedication of the easement as part of any Subdivision Certificate associated with\ninterallotment drainage.\n(11) (E039) An appropriately qualified and practising consultant is required to certify the following:\na. all drainage lines have been located within the respective easements, and\nb. any other drainage structures are located in accordance with the Construction Certificate.\nc. all stormwater has been directed to a Council approved drainage system\nd. all conditions of consent/ construction certificate approval have been complied with.\ne. Any on site detention system (if applicable) will function hydraulically in accordance with the approved\nConstruction Certificate.\n(12) (E049) A final Dilapidation Report including a photographic survey of the stormwater\nnetwork within the central corridor must be undertaken after the completion of\ninfrastructure works. A copy of this Dilapidation Report together with the accompanying\nphotographs must be given to the property owners. A copy must be submitted to Port\nMacquarie-Hastings Council and the Principal Certifying Authority prior to the issue of a\nSubdivision Certificate for the relevant stage/precinct.\nAny damage identified in the Dilapidation Report must be fully rectified by the applicant\nor owner at no cost to Council prior to the issue of Subdivision Certificate.\n(13) (E050) Prior to Council accepting new stormwater infrastructure, a CCTV inspection of\nall new and modified stormwater assets must be undertaken in accordance with the\nConduit Inspection Reporting Code of Australia WSA 05.\nA copy of the CCTV inspection footage and inspection report prepared and certified by a suitably qualified\nperson shall be provided to Council prior to the acceptance of works into the nominated ‘into maintenance\nperiod’.\n(14) (E053) All works shall be certified by a practicing Civil Engineer or Registered Surveyor as compliant with\nthe requirements of AUSPEC prior to issue of Subd ivision Certificate or release of the security bond,\nwhichever is to occur first for the relevant stage/precinct.\n(15) (E054) No building is to be conn ected to Council's future sewer main until Council has accepted such main.\nA pre-requisite for acceptance will be to successfully comply with Council's AUSPEC Specifications for air\ntesting, visual inspection, manhole lid seal and the level of the lids above the proposed finished surface\nlevel. The manhole must be protected during dwelling construction by erecting a barrier around the manhole.\nAny alterations to the finished su rface level requiring the raising or lo wering of the manhole will require\nCouncil's approval.\n(16) (E055) No building is to be connected to Council's future water main until Council has accepted such main.\nA pre-requisite for acceptance will be to successfully comply with Council's AUSPEC Specifications for\npressure testing of the main, hydrants and valves at the correct height in relation to the finished footpath\nand markers placed. The hydrant, valves and markers must be protected during dwelling construction by\nerecting a barrier. Hydrant, valves and markers are to be clearly visible at the completion of the dwelling\nlandscape works. Water meters will not be connected until the mains are accepted.\n(17) (E061) Landscaped areas being completed prior to issue of the Subdivision Certificate for the relevant\nstage/precinct. Public landscaping may be bonded as agreed to by Council.\n(18) (E064) Provision of street lighting to all new roads in accordance with AS1158 and compliance with the\nrequirements of the electricity authority regarding provision of electricity to serve the development.\nProvision shall be made for placement of conduits for future requirements or upgrades. Evidence by way of\nletter from the electricity provider, indicating compliance with this condition shall be submitted prior to the\nissue of the Subdivision Certificate for the relevant stage/precinct.\nAny proposal to erect non-standard, prestige or Smart Poles (or equivalent) street lighting shall:\n Forward all plans to the service provider for comment;\n Include instruction for completion of ‘Lighting Requirements’;\n be referred to Council together with details of the difference in annual charges over a twenty five (25)\nyear period in accordance with Policy R5 - Street Lighting on Public Roads;\n Supply to Council to keep in stock, one (1) extra pole for every six (6) r un of poles, for all poles that are\nnon-standard poles.\n(19) (E066) Ancillary works shall be undertaken at no cost to Council to make the engineering works required by\nthis Consent effective to the satisfaction of Director of Council’s Infrastructure Division. Such works shall\ninclude, but are not limited to the following:\na. The relocation of underground services where required by civil works being carried out.\nb. The relocation of above ground power and telephone services\nc. The relocation of street lighting\nd. The matching of new infrastructure into existing or future design infrastructure\n(20) (E068) Prior to the issue of a Subdivision Certif icate for the relevant stage/precinct, evidence to the\nsatisfaction of the Certifying Authority from the electricity and telecommuni cations providers that\nsatisfactory services arrangements have been made to the lots (including street lighting and fibre optic\ncabling where required).\n(21) (E072) Lodgement of a security deposit with Council upon practical completion of the subdivision works.\n(22) (E076) The plan of subdivision and Section 88B instrument shall establish the following restrictions,\neasements and/or covenants; with Council having the benefit and having the sole authority to release, vary\nor modify each restriction, easement and/or covenant. Wherever possible the extent of the land affected by\nthese covenants shall be defined by bearings and distances shown on the plan of subdivision:\na. Prohibiting direct vehicular access to and from Ocean Drive, except at designated road intersections.\nb. Prohibiting direct vehicular access for Lots 688, 17, 45 and 33 to and from Seaside Drive (currently within\nLot 1, DP 1225210).\nc. Prohibiting direct vehicular access for Lot 68 to and from Road #11.\nd. Prohibiting direct vehicular access for Lots 533, 558, 569, 570, 592, 624 and 652 to and from Wallum\nDrive (DA 2013/358 lead-in road).\ne. Prohibiting direct vehicular access for Lots 692 and 696 (north of Road #10) to and from Road No #2.\nf. No building shall be erected or permitted to remain erected upon any lot bur dened unless the building\nhas been designed to incorporate the required building construction category measures as outlined in\nthe Road Traffic Noise impact Assessment prepared by SLR Consulting dated 27 May 2016 to achieve\nthe acceptable daytime and night time noise levels contained within AS/NZS 2107:2000 - Acoustics -\nRecommended Design Sound Levels and Reverberation Times for Building Interiors.\ng. No pool shall be constructed or be permitted to remain on the lot burdened unless it has been designed\nto allow Koalas to escape by having a shallow end and/or a sloping bottom or otherwise incorporate a\nstout rope which is a minimum of 50mm in diameter with one end secured to a stable poolside structure\nand the other end trailing in the pool at all times.\nh. Provision within the title of proposed lots 68, 533 and 688 a restriction requiring corner boundary fencing\ntreatment to be constructed in accordance with PMH DCP 2011 (Rainbow Beach Area 14 Provisions).\nDetails are to be submitted to Council prior to issue of the Subdivision Certificate.\n(23) (E078) The lots identified as prop osed drainage land under Council’s control is to be dedicated to Council\nfor drainage, open space, road widening purposes. Provision for this dedication is to be made in the\napplication for the Subdivision Certificate for the relevant stage/precinct.\n(24) (E079) Submission to the Principal Certifying Authority of certification by a Registered Surveyor prior to the\nissue of a Subdivision Certificate for the relevant stage/precinct that all services and domestic drainage lines\nare wholly contained within the respective lots and easements.\n(25) (E080) The applicant is required to make provision in the applicatio n for a Subdivision Certificate for the\nrelevant stage/precinct:\na. dedication as public road of the area required for road widening,\nb. dedication as public road of a 3m splay corner on corner allotments unless otherwise agreed to by\nCouncil.\nc. consolidation of the existing allotments comprising the site of the proposed development.\n(26) (E081) The applicant will be require d to submit prior to the issue of a Subdivision Certificate for the relevant\nstage/precinct, a geotechnical report confirming construction of all earthworks in accordance with AUSPEC\nD6 and/or indicating the suitability of all allotments for future home/build ing sites; such report to provide\ndetails of:\na. The surface levels of the allotmen ts created and any other area fille d or reshaped as part of the\ndevelopment.\nb. Compaction testing carried out to Level 1 of Appendix B AS 3798.\nc. Standard penetration tests and calculated N values.\nd. Bore logs\ne. Site classification of all allotments in accordance with AS2870.2011 - Residential Slabs and Footings.\n(27) (E082) Submission of a complia nce certificate accompanying Works as Executed plans with detail included\nas required by Council’s current AUSPEC Specifications. The information is to be submitted in electronic\nformat in accordance with Council’s “CADCHECK” requirements detailing all infras tructure for Council to\nbring in to account its assets under the provisions of AAS27. This information is to be approved by Council\nprior to issue of a Subdivision Certificate for the relevant stage/precinct. The copyright for all information\nsupplied, shall be assigned to Council.\n(28) (E195) A Certificate of Compliance under the provis ions of Section 307 of the Water Management Act must\nbe obtained prior to the issue of a Subdivision Certificate for the relevant stage/precinct. The application for\nthe certificate is to include a copy of the Work-as-Executed plan and the Registered Surveyor’s Linen Plan.\n(29) (E197) Prior to the issue of a Subdivision Certifi cate for the relevant stage/precinct, a Validation Report\nprepared by a suitably qualified and practising contaminated land consultant shall be submitted to Port\nMacquarie-Hastings Council for the areas of the subdivision being developed for residential use and contain\ncontaminated and/or impacted soils or electricity power line/easement.\nRefer to the ERM Report “Rainbow Beach Propo sed Urban Development Ocean Drive Bonny Hills\nPreliminary Site Investigation” for Vincent’s Foundation Pty Ltd. Report No. 0072982 Dated November 2007.\n(30) (E198) The completion of all works required under Council's consent to Development Application No. DA\n2013/358 prior to the release of any Subdivision Certificate for Precinct A.\n(31) (E199) Satisfactory arrangements shall be made to ser vice lots, prior to any Subdivision Certificate releasing\nproposed Lot 700 (sporting fields) and Lot 701 (Southern School Site).\n(32) (A199) Prior to the issuing of any subdivision certi ficate within the relevant precinct/stage all associated\nenvironmental works are to be unde rtaken in accordance with the approv ed Vegetation Management Plan\nand to a standard to the satisfaction of Council.\n(33) Prior to the issuing of any subdivision certificate for lots within precincts G, H, I or J the central corridor\nenvironmental management land shall be dedicated to Port Macquarie-Hastings Council.","stage":"general","stage_basis":"heading","page":4}]});
